begin;create extension if not exists pgtap with schema extensions;select plan(18);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99600000-0000-4000-8000-000000000001','authenticated','authenticated','attendance-owner@example.test','',now(),'{"display_name":"Ana Owner"}',now(),now());set local role authenticated;select set_config('request.jwt.claim.sub','99600000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99600000-0000-4000-8000-000000000001","role":"authenticated"}',true);select public.create_business('attendance-test','Attendance Test','Attendance Test','sole_proprietorship','services','{}');select set_config('test.emp_org',(select id::text from public.organizations where slug='attendance-test'),true);select set_config('test.emp_branch',(select id::text from public.branches where organization_id=current_setting('test.emp_org')::uuid),true);
select throws_ok($$select public.save_employee(current_setting('test.emp_org')::uuid,null,current_setting('test.emp_branch')::uuid,'Juan Cruz','0917','Cashier','active',current_date-10,null)$$,'42501','Permission denied.','Disabled employee module rejects writes');reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.emp_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99600000-0000-4000-8000-000000000001',true);select public.set_business_module_state(current_setting('test.emp_org')::uuid,'employees',true,'{"employee_number_prefix":"TEAM"}');
select set_config('test.emp1',public.save_employee(current_setting('test.emp_org')::uuid,null,current_setting('test.emp_branch')::uuid,'Juan Cruz','09171234567','Cashier','active',current_date-10,null)::text,true);select results_eq($$select employee_number,name,position,employment_status from public.employees where id=current_setting('test.emp1')::uuid$$,$$select 'TEAM-000001'::text,'Juan Cruz'::text,'Cashier'::text,'active'::text$$,'Employee number and requested fields are stored');
select throws_ok($$select public.save_employee(current_setting('test.emp_org')::uuid,null,current_setting('test.emp_branch')::uuid,'Future Hire','','Staff','active',current_date+1,null)$$,'22023','Invalid employee.','Future hire dates are rejected');
select throws_ok($$select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'clock_in',now(),'{}',null,null,'disabled-clock')$$,'42501','Permission denied.','Disabled attendance module rejects clock events');
select lives_ok($$select public.set_business_module_state(current_setting('test.emp_org')::uuid,'attendance',true,'{"shift_start":"09:00","grace_period_minutes":5,"standard_day_minutes":480,"capture_location":true}')$$,'Attendance activates after Employees');
select set_config('test.emp_session',public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'clock_in',((current_date-1)::text||' 09:06+08')::timestamptz,'{"device":"tablet"}',14.5995,120.9842,'clock-in-1')::text,true);
select results_eq($$select work_date,is_late,status from public.attendance_sessions where id=current_setting('test.emp_session')::uuid$$,$$select current_date-1,true,'open'::text$$,'Clock-in derives the Manila work date and late arrival');select results_eq($$select latitude,longitude,device_info->>'device'from public.attendance_events where idempotency_key='clock-in-1'$$,$$select 14.5995::numeric,120.9842::numeric,'tablet'::text$$,'Optional device and location metadata are retained');
select results_eq($$select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'clock_in',((current_date-1)::text||' 09:06+08')::timestamptz,'{}',null,null,'clock-in-1')$$,$$select current_setting('test.emp_session')::uuid$$,'Clock-event retry is idempotent');select results_eq($$select count(*)from public.attendance_events where idempotency_key='clock-in-1'$$,$$select 1::bigint$$,'Retry cannot duplicate attendance');
select throws_ok($$select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'clock_in',((current_date-1)::text||' 09:07+08')::timestamptz,'{}',null,null,'clock-in-2')$$,'P0001','Employee already has an open attendance session.','Concurrent duplicate clock-in is rejected');
select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'break_start',((current_date-1)::text||' 12:00+08')::timestamptz,'{}',null,null,'break-start-1');select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'break_end',((current_date-1)::text||' 12:30+08')::timestamptz,'{}',null,null,'break-end-1');
select results_eq($$select break_minutes from public.attendance_sessions where id=current_setting('test.emp_session')::uuid$$,$$select 30$$,'Break duration is materialized from immutable events');select public.record_attendance_event(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'clock_out',((current_date-1)::text||' 17:30+08')::timestamptz,'{}',null,null,'clock-out-1');
select results_eq($$select status,worked_minutes,regular_minutes,overtime_minutes,payroll_status from public.attendance_sessions where id=current_setting('test.emp_session')::uuid$$,$$select 'closed'::text,474,474,0,'ready'::text$$,'Clock-out produces payroll-ready normalized minutes without calculating payroll');select results_eq($$select count(*)from public.attendance_events where session_id=current_setting('test.emp_session')::uuid$$,$$select 4::bigint$$,'Session retains complete immutable event history');
select throws_ok($$update public.attendance_events set event_type='clock_out'where idempotency_key='clock-in-1'$$,'42501','permission denied for table attendance_events','Clients cannot rewrite attendance events');
select lives_ok($$select public.save_employee(current_setting('test.emp_org')::uuid,current_setting('test.emp1')::uuid,current_setting('test.emp_branch')::uuid,'Juan Dela Cruz','09171234567','Senior Cashier','on_leave',current_date-10,null)$$,'Employee records can be maintained');select results_eq($$select name,position,employment_status from public.employees where id=current_setting('test.emp1')::uuid$$,$$select 'Juan Dela Cruz'::text,'Senior Cashier'::text,'on_leave'::text$$,'Employee edits retain the stable employee identity');
select results_eq($$select count(*)from public.employee_audit_history where employee_id=current_setting('test.emp1')::uuid$$,$$select 2::bigint$$,'Employee creation and updates are audited');select results_eq($$select count(*)from public.role_permissions assignment join public.roles role on role.id=assignment.role_id join public.permissions permission on permission.id=assignment.permission_id where role.organization_id=current_setting('test.emp_org')::uuid and role.key='manager'and(permission.key like'employee.%'or permission.key like'attendance.%')$$,$$select 5::bigint$$,'Managers receive employee and attendance permissions');select*from finish();rollback;
